import { CompactBase } from "transitive-class-base";

class DerivedCompact extends CompactBase {
  setOptions(value) {
    return `derived(${super.setOptions(value)})`;
  }

  render(value) {
    return `derived(${super.render(value)})`;
  }
}

/** @param {string} value @returns {string[]} */
function exercise(value) {
  const directBase = new CompactBase();
  const first = new DerivedCompact();
  const second = new DerivedCompact();
  const freshA = first.setOptions;
  const freshB = first.setOptions;
  const firstOptions = first.options;
  const secondOptions = second.options;
  return [
    directBase.render("direct"),
    first.render(value),
    second.render(value),
    `${freshA === freshA}|${freshB === freshB}|${firstOptions === firstOptions}`,
    firstOptions("x"),
    secondOptions("y"),
  ];
}

export { DerivedCompact, exercise };
